// Verifies Shopify's HMAC signature, then builds a pick list.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto in your n8n environment.
const crypto = require('crypto');
// Settings
const cfg = {
  shopify_webhook_secret: 'REPLACE_WITH_WEBHOOK_SIGNING_SECRET',
  fulfilment_email: 'warehouse@yourbusiness.com',
  from_email: 'orders@yourbusiness.com',
  slack_webhook_url: 'https://hooks.slack.com/services/REPLACE_ME',
};
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const raw = await this.helpers.getBinaryDataBuffer(i, 'data');
  const sent = (item.json.headers || {})['x-shopify-hmac-sha256'] || '';
  const calc = crypto.createHmac('sha256', cfg.shopify_webhook_secret).update(raw).digest('base64');
  const valid = sent.length === calc.length && crypto.timingSafeEqual(Buffer.from(sent), Buffer.from(calc));
  const o = item.json.body && item.json.body.id ? item.json.body : JSON.parse(raw.toString('utf8'));
  const a = o.shipping_address || {};
  const lines = (o.line_items || []).map(l => `${l.quantity} x ${l.sku || '-'}  ${l.title}${l.variant_title ? ' (' + l.variant_title + ')' : ''}`);
  out.push({ json: {
    valid,
    fulfilment_email: cfg.fulfilment_email, from_email: cfg.from_email, slack_webhook_url: cfg.slack_webhook_url,
    order: o.name,
    customer: [a.first_name, a.last_name].filter(Boolean).join(' '),
    ship_to: [a.address1, a.address2, a.city, a.province_code, a.zip, a.country_code].filter(Boolean).join(', '),
    shipping: (o.shipping_lines || []).map(s => s.title).join(', ') || 'standard',
    note: o.note || '',
    pick_list: lines.join('\n'),
    items: lines.length,
  } });
}
return out;
